CREATE TABLE IF NOT EXISTS `drivers` (`id` varchar(32) NOT NULL PRIMARY KEY, `name` varchar(120) NOT NULL, `lat` decimal(9,6) NOT NULL, `lon` decimal(9,6) NOT NULL, `available` boolean NOT NULL DEFAULT true, `committedRouteId` varchar(32), `shiftEndMin` int NOT NULL);
CREATE TABLE IF NOT EXISTS `vehicles` (`id` varchar(32) NOT NULL PRIMARY KEY, `capacityKg` int NOT NULL, `available` boolean NOT NULL DEFAULT true, `fuelL` decimal(8,2) NOT NULL, `co2KgPerKm` decimal(6,3) NOT NULL, `costPerKm` decimal(7,3) NOT NULL, `driverId` varchar(32) NOT NULL);
CREATE TABLE IF NOT EXISTS `stops` (`id` varchar(32) NOT NULL PRIMARY KEY, `name` varchar(160) NOT NULL, `lat` decimal(9,6) NOT NULL, `lon` decimal(9,6) NOT NULL, `demandKg` int NOT NULL, `priority` enum('Critical','Urgent','Normal') NOT NULL, `deadlineMin` int NOT NULL, `serviceMin` int NOT NULL, `routeId` varchar(32) NOT NULL, `committed` boolean NOT NULL DEFAULT true, `completed` boolean NOT NULL DEFAULT false, `cancelled` boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS `routes` (`id` varchar(32) NOT NULL PRIMARY KEY, `vehicleId` varchar(32) NOT NULL, `driverId` varchar(32) NOT NULL, `currentStopIndex` int NOT NULL, `distanceCompletedKm` decimal(8,2) NOT NULL, `distanceRemainingKm` decimal(8,2) NOT NULL, `etaMin` int NOT NULL, `status` enum('On route','At risk','Recovering','Complete') NOT NULL, `stopIds` text NOT NULL);
CREATE TABLE IF NOT EXISTS `disruptions` (`id` varchar(48) NOT NULL PRIMARY KEY, `type` enum('road','vehicle_unavailable','urgent_addition','cancellation','capacity_shortage') NOT NULL, `targetId` varchar(32) NOT NULL, `severity` enum('Critical','Urgent','Normal') NOT NULL, `description` text NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `experimentRuns` (`id` int AUTO_INCREMENT PRIMARY KEY, `scenarioName` varchar(180) NOT NULL, `disruptionId` varchar(48) NOT NULL, `planner` enum('baseline','reliefroute') NOT NULL, `elapsedMs` decimal(10,2) NOT NULL, `serviceRate` decimal(6,2) NOT NULL, `protectedPct` decimal(6,2) NOT NULL, `distanceKm` decimal(10,2) NOT NULL, `cost` decimal(10,2) NOT NULL, `emissionsKg` decimal(10,2) NOT NULL, `score` decimal(6,2) NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
